cases as (select c.p,c.description,case when c.k is null then b.f when c.remove then b.f-c.k else jsonb_set(b.f,array[c.k],to_jsonb(case when c.repeat is null then c.v else repeat(c.v,c.repeat) end)) end f,c.expected from raw_cases c join baselines b using(p)
union all values ('unknown','unknown profile','{}'::jsonb,false),('coiffure','array rejected','[]'::jsonb,false),('coiffure','scalar rejected','"invalid"'::jsonb,false),('coiffure','non-string field','{"style":"coupe","technique":42}'::jsonb,false)),
results as (select *,public.ns_activity_workflow_fields_valid(p,f) actual from cases)
select count(*) tested,count(*) filter(where expected) valid_cases,count(*) filter(where not expected) invalid_cases,count(*) filter(where actual is distinct from expected) mismatches,coalesce(jsonb_agg(jsonb_build_object('profile',p,'case',description,'expected',expected,'actual',actual)) filter(where actual is distinct from expected),'[]'::jsonb) differences from results;
do $qa$ begin if (select tested from ns_qa_field_matrix)<>365 or (select mismatches from ns_qa_field_matrix)<>0 then raise exception 'ACTIVITY_FIELD_MATRIX_FAILURE: %',(select differences from ns_qa_field_matrix);end if;end $qa$;
select * from ns_qa_field_matrix;
